from azure.cosmos import CosmosClient
import os


def get_cosmos_client():
    cosmos_endpoint = os.environ.get("AZURE_COSMOS_ENDPOINT")
    cosmos_key = os.environ.get("AZURE_COSMOS_KEY")
    if not cosmos_endpoint or not cosmos_key:
        raise ValueError("AZURE_COSMOS_ENDPOINT and AZURE_COSMOS_KEY environment variables must be set.")
    return CosmosClient(cosmos_endpoint, credential=cosmos_key)


def get_container_client(database_name, container_name):
    client = get_cosmos_client()
    database_client = client.get_database_client(database_name)
    container_client = database_client.get_container_client(container_name)
    return container_client

from typing import Dict, Any, Optional


class Document:
    def __init__(self, id: str, content: Dict[str, Any], etag: Optional[str] = None):
        self.id = id
        self.content = content
        self.etag = etag

    def to_dict(self):
        doc_dict = {"id": self.id, **self.content}
        if self.etag:
            doc_dict["_etag"] = self.etag
        return doc_dict

    @staticmethod
    def from_dict(doc_dict: Dict[str, Any]):
        doc_id = doc_dict.pop("id")
        etag = doc_dict.pop("_etag", None)
        return Document(id=doc_id, content=doc_dict, etag=etag)

from vertexai.preview.generative_models import GenerativeModel, HarmCategory, HarmBlockThreshold
import os


def record_text_safety(text_content: str) -> dict:
    model = GenerativeModel("gemini-pro") # Using gemini-pro for content analysis as well

    # Configure safety settings to get a detailed breakdown, not just blocking
    # We set thresholds to BLOCK_NONE to get scores for all categories
    safety_settings = {
        HarmCategory.HARM_CATEGORY_HARASSMENT: HarmBlockThreshold.BLOCK_NONE,
        HarmCategory.HARM_CATEGORY_HATE_SPEECH: HarmBlockThreshold.BLOCK_NONE,
        HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT: HarmBlockThreshold.BLOCK_NONE,
        HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT: HarmBlockThreshold.BLOCK_NONE,
    }

    response = model.generate_content(
        text_content,
        safety_settings=safety_settings
    )

    # The safety attributes are usually in the candidates[0].safety_ratings
    safety_ratings = []
    if response.candidates and response.candidates[0].safety_ratings:
        for rating in response.candidates[0].safety_ratings:
            safety_ratings.append({
                "category": rating.category.name,
                "probability": rating.probability.name,
                "blocked": rating.blocked
            })

    return {"safety_ratings": safety_ratings}

from google.cloud import translate_v2 as translate
import os


def record_translate(text: str, target_language: str) -> dict:
    translate_client = translate.Client()

    # Target can be a language code, such as "en" or "es".
    response = translate_client.translate(text, target_language=target_language)

    return {
        "translated_text": response["translatedText"],
        "source_language": response["detectedSourceLanguage"],
    }
